// Carte memoire PS1 vierge formatee (128 Kio, en-tete MC, structure standard
// PCSX-ReARMed) generee par le coeur reel (tools/browser_memcard_probe.py).
// Injectee au boot quand aucune batterie n'existe : sans .srm, le jeu affiche
// « no memory card » sans pouvoir formater. Base64 : extensions .srm bloquees.
export const EMPTY_MEMCARD_B64 = "";
export function emptyMemcardBytes() {
  const bin = atob(EMPTY_MEMCARD_B64), out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
